css:
/* Global Reset and Typography */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

.payslip-document {
    font-family: Tahoma, Arial, sans-serif;
    color: #1a1a1a;
    background-color: #ffffff;
    max-width: 850px;
    margin: 0 auto;
    font-size: 14px;
    line-height: 1.6;
}

/* Document Header */
.document-header {
    background-color: #f8f9fa;
    border-bottom: 3px solid #00844E;
    padding: 15px;
    margin-bottom: 15px;
}

.header-content {
    display: table;
    width: 100%;
}

.document-title {
    display: table-cell;
    vertical-align: middle;
}

.document-title h1 {
    font-size: 32px;
    font-weight: 300;
    letter-spacing: -1px;
    color: #072B1A;
    margin: 0;
}

.document-subtitle {
    font-size: 12px;
    color: #6c757d;
    font-weight: 600;
    letter-spacing: 1px;
    margin-top: 5px;
}

.document-meta {
    display: table-cell;
    vertical-align: middle;
    text-align: right;
}

.meta-item {
    margin-bottom: 5px;
}

.meta-label {
    font-size: 12px;
    color: #6c757d;
    margin-right: 8px;
}

.meta-value {
    font-size: 13px;
    font-weight: 600;
    color: #072B1A;
}

/* Information Card */
.info-card {
    background-color: #ffffff;
    border: 1px solid #e9ecef;
    border-radius: 8px;
    margin-bottom: 25px;
    overflow: hidden;
}

.card-header {
    background-color: #00844E;
    color: white;
    padding: 12px 20px;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.5px;
}

.info-table {
    width: 100%;
    padding: 20px;
}

.info-group {
    width: 33.33%;
    padding: 0 20px;
    border-right: 1px solid #e9ecef;
}

.info-group:last-child {
    border-right: none;
}

.info-row {
    margin-bottom: 12px;
}

.info-label {
    display: block;
    font-size: 11px;
    color: #6c757d;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 2px;
}

.info-value {
    display: block;
    font-size: 15px;
    font-weight: 600;
    color: #072B1A;
}

/* Salary Breakdown */
.salary-breakdown {
    margin-bottom: 25px;
}

.breakdown-table {
    width: 100%;
}

.earnings-section, .deductions-section {
    width: 48%;
    background-color: #ffffff;
    border: 1px solid #e9ecef;
    border-radius: 8px;
    vertical-align: top;
}

.divider {
    width: 4%;
}

.section-title {
    background-color: #f8f9fa;
    padding: 12px 20px;
    font-size: 13px;
    font-weight: 600;
    color: #495057;
    border-bottom: 1px solid #e9ecef;
    letter-spacing: 0.5px;
}

.component-table {
    width: 100%;
    padding: 15px 20px;
}

.component-table tr {
    border-bottom: 1px solid #f1f3f5;
}

.component-table tr:last-child {
    border-bottom: none;
}

.component-desc {
    padding: 8px 0;
    font-size: 13px;
    color: #495057;
}

.component-value {
    padding: 8px 0;
    text-align: right;
    font-size: 13px;
    font-weight: 600;
    color: #1a1a1a;
}

.section-total {
    background-color: #f8f9fa;
    padding: 15px 20px;
    border-top: 2px solid #e9ecef;
    display: table;
    width: 100%;
    font-size: 14px;
    font-weight: 600;
}

.section-total span:first-child {
    display: table-cell;
    color: #072B1A;
}

.section-total span:last-child {
    display: table-cell;
    text-align: right;
    color: #00844E;
}

/* Net Pay Container */
.net-pay-container {
    background: linear-gradient(135deg, #00844E 0%, #072B1A 100%);
    border-radius: 8px;
    padding: 30px;
    margin-bottom: 25px;
    text-align: center;
    position: relative;
    overflow: hidden;
}

.net-pay-container::before {
    content: '';
    position: absolute;
    top: -50%;
    right: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 70%);
}

.net-pay-content {
    position: relative;
    z-index: 1;
}

.net-pay-main {
    display: block;
}

.net-label {
    display: block;
    font-size: 14px;
    color: rgba(255,255,255,0.9);
    letter-spacing: 2px;
    margin-bottom: 10px;
}

.net-amount {
    display: block;
    font-size: 36px;
    font-weight: 300;
    color: white;
    letter-spacing: -1px;
}

.net-pay-words {
    font-size: 13px;
    color: rgba(255,255,255,0.8);
    margin-top: 10px;
    text-transform: capitalize;
}

/* Attendance Card */
.attendance-card {
    background-color: #ffffff;
    border: 1px solid #e9ecef;
    border-radius: 8px;
    margin-bottom: 25px;
    overflow: hidden;
}

.attendance-table {
    width: 100%;
    padding: 20px;
}

.attendance-item {
    width: 25%;
    text-align: center;
    padding: 10px;
}

.att-value {
    font-size: 28px;
    font-weight: 300;
    color: #00844E;
    margin-bottom: 5px;
}

.att-label {
    font-size: 11px;
    color: #6c757d;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* YTD Summary */
.ytd-summary {
    background-color: #f8f9fa;
    border-radius: 8px;
    padding: 20px;
    margin-bottom: 30px;
}

.ytd-table {
    width: 100%;
}

.ytd-item {
    width: 50%;
    padding: 0 20px;
}

.ytd-label {
    display: block;
    font-size: 12px;
    color: #6c757d;
    margin-bottom: 5px;
}

.ytd-value {
    display: block;
    font-size: 18px;
    font-weight: 600;
    color: #072B1A;
}

/* Document Footer */
.document-footer {
    border-top: 1px solid #e9ecef;
    padding-top: 20px;
    margin-top: 40px;
    text-align: center;
}

.footer-note {
    font-size: 11px;
    color: #6c757d;
    margin-bottom: 10px;
    font-style: italic;
}

.footer-contact {
    font-size: 10px;
    color: #adb5bd;
}

/* Print Styles */
@media print {
    .payslip-document {
        font-size: 12px;
    }
    
    .document-header,
    .card-header,
    .net-pay-container,
    .section-title,
    .ytd-summary {
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }
    
    .net-pay-container {
        background: #00844E !important;
    }
    
    .info-card,
    .earnings-section,
    .deductions-section,
    .attendance-card {
        page-break-inside: avoid;
    }
    
    .document-footer {
        position: fixed;
        bottom: 0;
        width: 100%;
    }
}
